input.sparql:
SELECT DISTINCT ?p ?pc ?ts WHERE {
  ?p ref:hasTimeseriesId ?ts .
  ?p a ?pc .
  FILTER (?pc IN (brick:TemperatureSensor, brick:CoolingSetpoint, brick:CoolingSetpointSensor, brick:Zone))
}

SELECT DISTINCT ?pc (COUNT(?p) AS ?c) WHERE {
  ?p a ?pc .
} GROUP BY ?pc ORDER BY ?c

SELECT ?zone ?zname ?tempsensor ?tref ?sp ?spref WHERE {
  ?z a brick:HVAC_Zone .
  OPTIONAL { ?z rdfs:label ?zname }
  ?t a brick:Zone_Air_Temperature_Sensor ; brick:hasLocation ?z .
  ?t ref:hasExternalReference ?tref .
  ?sp a brick:Zone_Air_Cooling_Temperature_Setpoint .
  ?spref ref:hasTimeseriesId ?spref .
} LIMIT 5

SELECT DISTINCT ?p WHERE {
  ?p a brick:Zone_Air_Cooling_Temperature_Setpoint .
  ?p brick:hasLocation ?z .
} LIMIT 5

SELECT DISTINCT ?p ?loc WHERE {
  ?p a brick:Zone_Air_Cooling_Temperature_Setpoint .
  ?p brick:hasLocation ?loc .
} LIMIT 5

SELECT ?z ?zname ?sp ?sptsid ?t ?tsid WHERE {
  ?sp a brick:Zone_Air_Cooling_Temperature_Setpoint .
  ?sp brick:isPointOf ?z .
  ?sp ref:hasExternalReference ?sptsid .
  ?t a brick:Zone_Air_Temperature_Sensor .
  ?t brick:isPointOf ?z .
  ?t ref:hasExternalReference ?tsid .
  OPTIONAL { ?z rdfs:label ?zname }
}
